// src/components/AdminDashboard.js
import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios'; // Keep axios for now, but prefer authenticated API client
// FIX: Corrected import path for API functions
import { fetchCustomers, addCustomer as apiAddCustomer } from '../api/customers';
import { fetchInventoryItems, transferInventory, fetchInventoryByLocation, fetchLocations } from '../api/inventory';
import { recordSale, fetchDueBills, fetchOverdueBills } from '../api/sales';
import { useAuth } from '../context/AuthContext';

const AdminDashboard = () => {
  // --- State for User Management ---
  const [users, setUsers] = useState([]);
  const [usersLoading, setUsersLoading] = useState(true);

  // --- State for Inventory Management (Add Item) ---
  const [inventoryItems, setInventoryItems] = useState([]);
  const [newItemName, setNewItemName] = useState('');
  const [newItemPrice, setNewItemPrice] = useState('');
  const [newItemQuantity, setNewItemQuantity] = useState('');
  const [inventoryLoading, setInventoryLoading] = useState(true);

  // --- State for Sales Entry ---
  const [customers, setCustomers] = useState([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [showAddCustomerForm, setShowAddCustomerForm] = useState(false);
  const [saleItems, setSaleItems] = useState([]);
  const [discountAmount, setDiscountAmount] = useState(0);
  const [discountPercentage, setDiscountPercentage] = useState(0);
  const [paymentMethod, setPaymentMethod] = useState('cash');
  const [customerFetchError, setCustomerFetchError] = useState('');
  const [saleError, setSaleError] = useState('');
  const [saleLoading, setSaleLoading] = useState(false);
  const [dueDate, setDueDate] = useState(''); // FIX: Declared dueDate state

  // --- State for Item Selection in Sale ---
  const [selectedItemId, setSelectedItemId] = useState('');
  const [currentQuantity, setCurrentQuantity] = useState(1);
  const [selectedLocation, setSelectedLocation] = useState(''); // FIX: Declared selectedLocation state

  // --- State for Inventory Transfers ---
  const [transferItemId, setTransferItemId] = useState('');
  const [transferQuantity, setTransferQuantity] = useState(1);
  const [fromLocation, setFromLocation] = useState('');
  const [toLocation, setToLocation] = useState('');
  const [locations, setLocations] = useState([]);
  const [locationLoading, setLocationLoading] = useState(true); // FIX: Declared locationLoading state
  const [transferLoading, setTransferLoading] = useState(false);
  const [transferError, setTransferError] = useState('');

  // --- State for Credit Bills ---
  const [dueBills, setDueBills] = useState([]);
  const [overdueBills, setOverdueBills] = useState([]);
  const [creditBillsLoading, setCreditBillsLoading] = useState(true);

  const newCustomerFormRef = useRef(null); // Ref for focusing the select after adding a customer

  // --- Auth Context ---
  const { currentUser, logout } = useAuth();
  // If you have an authenticated API client: const { api } = useAuth();

  // --- State for General Errors ---
  const [error, setError] = useState(null); // General error state for user/inventory

  // --- Loading State for Customers ---
  const [loadingCustomers, setLoadingCustomers] = useState(true); // FIX: Declared loadingCustomers state

  // --- Effects to Fetch Initial Data ---
  useEffect(() => {
    fetchUsers();
    fetchInventory();
    fetchCustomersData();
    fetchLocationsData();     // Fetch locations for transfers
    fetchCreditBillsData();   // Fetch due/overdue bills
  }, []);

  // --- User Management Functions ---
  const fetchUsers = async () => {
    setUsersLoading(true);
    setError(null);
    try {
      const response = await axios.get('/api/admin/users');
      setUsers(response.data.data);
    } catch (err) {
      console.error('Error fetching users:', err);
      setError('Failed to fetch users. Please try again.');
    } finally {
      setUsersLoading(false);
    }
  };

  const updateUserRole = async (userId, newRole) => {
    try {
      await axios.put(`/api/admin/users/${userId}/role`, { role: newRole });
      fetchUsers();
    } catch (err) {
      console.error('Error updating user role:', err);
      setError('Failed to update user role.');
    }
  };

  const deleteUser = async (userId) => {
    if (window.confirm('Are you sure you want to delete this user?')) {
      try {
        await axios.delete(`/api/admin/users/${userId}`);
        fetchUsers();
      } catch (err) {
        console.error('Error deleting user:', err);
        setError('Failed to delete user.');
      }
    }
  };

  // --- Inventory Management Functions (for adding new inventory items) ---
  const fetchInventory = async () => {
    setInventoryLoading(true);
    setError(null);
    try {
      const response = await axios.get('/api/admin/inventory');
      setInventoryItems(response.data.data);
    } catch (err) {
      console.error('Error fetching inventory:', err);
      setError('Failed to fetch inventory. Please try again.');
    } finally {
      setInventoryLoading(false);
    }
  };

  const handleAddNewInventoryItem = async (e) => {
    e.preventDefault();
    if (!newItemName || !newItemPrice || !newItemQuantity) {
      alert('Please fill in all fields for the new inventory item.');
      return;
    }
    const price = parseFloat(newItemPrice);
    const quantity = parseInt(newItemQuantity, 10);
    if (isNaN(price) || price < 0) {
      alert('Please enter a valid price (non-negative number).');
      return;
    }
    if (isNaN(quantity) || quantity < 0) {
      alert('Please enter a valid quantity (non-negative integer).');
      return;
    }
    try {
      await axios.post('/api/admin/inventory', { name: newItemName, price, quantity });
      fetchInventory();
      setNewItemName(''); setNewItemPrice(''); setNewItemQuantity('');
      alert('Item added successfully!');
    } catch (err) {
      console.error('Error adding item:', err);
      setError('Failed to add item.');
    }
  };

  // --- Sales Entry Functions ---
  const fetchCustomersData = async () => {
    setCustomerFetchError('');
    setLoadingCustomers(true);
    try {
      const fetchedCustomers = await fetchCustomers();
      setCustomers(fetchedCustomers);
    } catch (err) {
      console.error("Error fetching customers:", err);
      setCustomerFetchError('Failed to load customers. Please try again.');
    } finally {
      setLoadingCustomers(false);
    }
  };

  const handleCustomerChange = (e) => {
    setSelectedCustomerId(e.target.value);
    setSaleError('');
  };

  const handleAddNewCustomerClick = () => { setShowAddCustomerForm(true); };
  const handleCloseAddCustomerForm = () => { setShowAddCustomerForm(false); };

  const handleCustomerAdded = (newCustomer) => {
    setCustomers(prevCustomers => [...prevCustomers, newCustomer].sort((a, b) => a.name.localeCompare(b.name)));
    setSelectedCustomerId(newCustomer._id);
    setShowAddCustomerForm(false);
  };

  const handleAddItemToSale = (itemToAdd) => {
    const existingItemIndex = saleItems.findIndex(saleItem => saleItem.itemId === itemToAdd.itemId);
    let updatedSaleItems;
    if (existingItemIndex > -1) {
      updatedSaleItems = [...saleItems];
      const existingItem = updatedSaleItems[existingItemIndex];
      const newQuantity = existingItem.quantity + itemToAdd.quantity;
      const currentInventoryItem = inventoryItems.find(invItem => invItem._id === itemToAdd.itemId);
      if (currentInventoryItem && newQuantity > currentInventoryItem.quantity) {
        alert(`Cannot add more. Insufficient stock for ${itemToAdd.name}. Available: ${currentInventoryItem.quantity}`);
        return;
      }
      updatedSaleItems[existingItemIndex] = { ...existingItem, quantity: newQuantity };
    } else {
      updatedSaleItems = [...saleItems, itemToAdd];
    }
    setSaleItems(updatedSaleItems);
    setSaleError('');
  };

  const handleRemoveSaleItem = (indexToRemove) => {
    setSaleItems(saleItems.filter((_, index) => index !== indexToRemove));
  };

  const handleSubmitSale = async () => {
    if (!selectedCustomerId) { setSaleError('Please select a customer.'); return; }
    if (saleItems.length === 0) { setSaleError('Please add items to the sale.'); return; }

    setSaleLoading(true);
    setSaleError('');

    const saleData = {
      customerId: selectedCustomerId,
      items: saleItems.map(item => ({
        itemId: item.itemId, quantity: item.quantity, priceAtSale: item.priceAtSale, name: item.name, locationTakenFrom: item.locationTakenFrom
      })),
      discountAmount, discountPercentage, paymentMethod,
      ...(paymentMethod === 'credit' && dueDate && { dueDate: dueDate }), // FIX: Only add dueDate if it's a credit sale and dueDate is present
    };

    if (paymentMethod === 'credit' && !dueDate) {
      setSaleError('Please enter a due date for credit sales.');
      setSaleLoading(false);
      return;
    }
    if (paymentMethod === 'credit' && !selectedCustomerId) {
      setSaleError('Please select a customer for credit sales.');
      setSaleLoading(false);
      return;
    }

    try {
      const response = await axios.post('/api/sales/entry', saleData);
      alert(`Sale recorded successfully! Sale ID: ${response.data._id}`);
      setSelectedCustomerId(''); setSaleItems([]); setDiscountAmount(0); setDiscountPercentage(0); setPaymentMethod('cash');
      setDueDate(''); // FIX: Reset dueDate
      fetchCustomersData(); fetchInventory();
    } catch (error) {
      console.error('Sale Submission Error:', error);
      setSaleError(error.response?.data?.message || 'Failed to record sale. Please check stock and try again.');
    } finally {
      setSaleLoading(false);
    }
  };

  // --- Inventory Transfer Functions ---
  const fetchLocationsData = async () => {
      setLocationLoading(true); // FIX: Set location loading state
      try {
          const locs = await fetchLocations();
          setLocations(locs);
      } catch (err) {
          console.error("Error fetching locations:", err);
          setError("Failed to load locations."); // Using general error state
      } finally {
          setLocationLoading(false); // FIX: Clear location loading state
      }
  };

  const fetchCreditBillsData = async () => {
      setCreditBillsLoading(true);
      try {
          const due = await fetchDueBills();
          const overdue = await fetchOverdueBills();
          setDueBills(due);
          setOverdueBills(overdue);
      } catch (err) {
          console.error("Error fetching credit bills:", err);
          setError("Failed to load credit bills."); // Using general error state
      } finally {
          setCreditBillsLoading(false);
      }
  };

  const handleInventoryTransfer = async (e) => {
      e.preventDefault();
      if (!transferItemId || !fromLocation || !toLocation || transferQuantity < 1) {
          setTransferError("Please fill in all transfer details.");
          return;
      }
      setTransferLoading(true);
      setTransferError('');
      try {
          await transferInventory({ itemId: transferItemId, fromLocation, toLocation, quantity: transferQuantity });
          alert('Inventory transferred successfully!');
          fetchInventory(); // Refresh inventory list
          setTransferItemId(''); setFromLocation(''); setToLocation(''); setTransferQuantity(1);
      } catch (err) {
          setTransferError(err.response?.data?.message || 'Transfer failed.');
      } finally {
          setTransferLoading(false);
      }
  };

  // --- Calculations for Sale Summary ---
  let subtotal = saleItems.reduce((sum, item) => sum + item.priceAtSale * item.quantity, 0);
  let totalAfterDiscount = subtotal;
  if (discountPercentage > 0) { const percentageDiscountValue = (subtotal * discountPercentage) / 100; totalAfterDiscount = subtotal - percentageDiscountValue; }
  if (discountAmount > 0) { totalAfterDiscount = totalAfterDiscount - discountAmount; }
  totalAfterDiscount = Math.max(0, totalAfterDiscount);

  // --- Combined Loading State ---
  const overallLoading = usersLoading || inventoryLoading || saleLoading || loadingCustomers || creditBillsLoading;

  if (overallLoading) {
    return <div className="flex justify-center items-center h-screen">Loading...</div>;
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Navbar */}
      <nav className="bg-white shadow">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16">
            <div className="flex items-center">
              <h1 className="text-xl font-semibold text-red-600">Admin Dashboard</h1>
            </div>
            <div className="flex items-center space-x-4">
              <span className="text-gray-700">Welcome, {currentUser?.username || 'Admin'}</span>
              <button onClick={logout} className="bg-red-600 hover:bg-red-700 text-white px-4 py-2 rounded-md text-sm font-medium">Logout</button>
            </div>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <div className="max-w-7xl mx-auto py-6 sm:px-6 lg:px-8">
        <div className="px-4 py-6 sm:px-0">

          {/* Display Errors */}
          {(error || customerFetchError || saleError || transferError) && (
            <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded relative mb-8" role="alert">
              <strong className="font-bold">Error:</strong>
              <span className="block sm:inline"> {error || customerFetchError || saleError || transferError}</span>
              <span className="absolute top-0 bottom-0 right-0 px-4 py-3">
                <button onClick={() => { setError(null); setCustomerFetchError(null); setSaleError(null); setTransferError(null); }} className="text-red-700 hover:text-red-900">
                  <svg className="fill-current h-6 w-6 text-red-500" role="button" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><title>Close</title><path d="M14.348 14.849c-0.469 0.469-1.229 0.469-1.697 0L10 11.819l-2.651 3.029c-0.469 0.469-1.229 0.469-1.697 0-0.469-0.469-0.469-1.229 0-1.697l2.651-3.029L5.651 5.651c-0.469-0.469-0.469-1.229 0-1.697c0.469-0.469 1.229-0.469 1.697 0L10 8.181l2.651-3.029c0.469-0.469 1.229-0.469 1.697 0c0.469 0.469 0.469 1.229 0 1.697L11.819 10l3.029 2.651c0.469 0.469 0.469 1.229 0 1.697z"/></svg>
                </button>
              </span>
            </div>
          )}

          {/* Stats Overview */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
            <div className="bg-white overflow-hidden shadow rounded-lg">
              <div className="p-5">
                <div className="flex items-center">
                  <div className="flex-shrink-0"><div className="h-10 w-10 bg-blue-500 rounded-full flex items-center justify-center"><span className="text-white">👥</span></div></div>
                  <div className="ml-5 w-0 flex-1"><dl><dt className="text-sm font-medium text-gray-500 truncate">Total Users</dt><dd className="text-2xl font-bold text-gray-900">{users.length}</dd></dl></div>
                </div>
              </div>
            </div>
            <div className="bg-white overflow-hidden shadow rounded-lg">
              <div className="p-5">
                <div className="flex items-center">
                  <div className="flex-shrink-0"><div className="h-10 w-10 bg-green-500 rounded-full flex items-center justify-center"><span className="text-white">📦</span></div></div>
                  <div className="ml-5 w-0 flex-1"><dl><dt className="text-sm font-medium text-gray-500 truncate">Total Inventory Items</dt><dd className="text-2xl font-bold text-gray-900">{inventoryItems.length}</dd></dl></div>
                </div>
              </div>
            </div>
          </div>

          {/* Add New Item Form */}
          <div className="bg-white shadow overflow-hidden sm:rounded-lg mb-8">
            <div className="px-4 py-5 sm:p-6">
              <h3 className="text-lg leading-6 font-medium text-gray-900">Add New Inventory Item</h3>
              <form onSubmit={handleAddNewInventoryItem} className="mt-5 grid grid-cols-1 gap-y-6 sm:grid-cols-3">
                <div>
                  <label htmlFor="itemName" className="block text-sm font-medium text-gray-700">Item Name</label>
                  <div className="mt-1"><input type="text" id="itemName" value={newItemName} onChange={(e) => setNewItemName(e.target.value)} required className="shadow-sm focus:ring-red-500 focus:border-red-500 block w-full sm:text-sm border-gray-300 rounded-md p-2" placeholder="e.g., Laptop" /></div>
                </div>
