                        const itemAtSelectedLocation = inventoryItems.find(i => i._id === selectedItemId && i.location === e.target.value);
                        if (!itemAtSelectedLocation) {
                          setSaleError(`Item "${item.name}" not available at "${e.target.value}".`);
                        } else if (currentQuantity > itemAtSelectedLocation.quantity) {
                          setCurrentQuantity(itemAtSelectedLocation.quantity > 0 ? itemAtSelectedLocation.quantity : 1);
                        }
                      }
