                      if (!selectedItem) { setSaleError('Selected item not found.'); return; }
                      const itemAtSelectedLocation = inventoryItems.find(i => i._id === selectedItemId && i.location === selectedLocation);
                      if (!itemAtSelectedLocation || itemAtSelectedLocation.quantity < currentQuantity) {
                        alert(`Cannot add more. Insufficient stock for ${selectedItem.name} at ${selectedLocation}. Available: ${itemAtSelectedLocation?.quantity || 0}`);
                        return;
                      }
                      handleAddItemToSale({
                        itemId: selectedItem._id,
                        name: selectedItem.name,
                        quantity: currentQuantity,
                        priceAtSale: selectedItem.price,
                        locationTakenFrom: selectedLocation,
                      });
                      setSelectedItemId(''); setCurrentQuantity(1); setSelectedLocation('');
