                              <td className="px-4 py-2 whitespace-nowrap text-sm font-medium text-red-900">{bill.customerName}</td>
                              <td className="px-4 py-2 whitespace-nowrap text-sm text-red-700">${bill.totalAmount.toFixed(2)}</td>
                              <td className="px-4 py-2 whitespace-nowrap text-sm text-red-700">{new Date(bill.dueDate).toLocaleDateString()}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    )}
                  </div>
                </>
              )}
            </div>
          </div>

        </div> {/* End px-0 */}
      </div> {/* End py-6 */}
    </div> 
  );
};

export default AdminDashboard;
